# Hypothesis: DLA per layer for </think> at close position and Wait positions
r = r_plus.detach().numpy().astype(np.float64)
acts = {}
for L in range(24):
    acts[L] = np.load(f'/work/fwd_2/mlp_act_L{L}.npy').astype(np.float64)  # [text, pos, 3584]
meta = json.load(open('/work/fwd_2/meta.json')); lengths = meta['lengths']; tids = meta['token_ids']
coef = {}
for L in range(24):
    W = load(f'model.language_model.layers.{L}.mlp.down_proj.weight').float().numpy().astype(np.float64)  # [1024,3584]
    coef[L] = r @ W  # [3584]
    del W

def dla(L, ti, p):
    return float(acts[L][ti, p] @ coef[L])
print('per-layer MLP contribution to </think> logit at text5 close-pos 128:')
tot=0
for L in range(24):
    v = dla(L, 5, 128); tot+=v
    print(L, round(v,3))
print('total', round(tot,3))

# Find all positions in texts where the next token decodes to contain 'Wait'
for ti in range(6):
    L = lengths[ti]; t = tids[ti][:L]
    hits=[]
    for i in range(L-1):
        d = tok.decode([t[i+1]])
        if 'Wait' in d:
            hits.append((i, repr(d)))
    print('text', ti, hits)

for (ti,p) in [(5,128),(0,484),(0,538),(2,288)]:
    print('='*60); print('text',ti,'pos',p,'next', tok.decode([tids[ti][p+1]]))
    rows_=[]
    for L in range(24):
        a = acts[L][ti,p]
        contrib = a*coef[L]
        aj = np.argsort(-np.abs(contrib))[:3]
        for j in aj:
            rows_.append((L, int(j), float(a[j]), float(coef[L][j]), float(contrib[j])))
    rows_.sort(key=lambda x: -abs(x[4]))
    for L,j,a,c,v in rows_[:12]:
        print(f'L{L:2d} u{j:5d} act{a:+.2f} coef{c:+.3f} contrib{v:+.3f}')

cut_sorted = sorted(cut, key=lambda r: -r['text'].count('Wait'))
for r in cut_sorted[:14]:
    print(r['qid'], r['tokens'], 'waits', r['text'].count('Wait'), 'close', r['text'].count('</think>'))

for (ti,p) in [(0,484),(0,538),(2,288)]:
    print('='*40, 'text', ti, 'pos', p, 'next', repr(tok.decode([tids[ti][p+1]])))
    for k in range(12):
        tid = topk_ids[ti,p,k]; lp = topk_lp[ti,p,k]
        print(' ', k, tid, repr(tok.decode([tid])), round(float(lp),3))

